RIDES = [
    ('No operating rides; the park closed in 2001 and was left standing for years before demolition', 'closed park'),
]
print('Ride-type classifier for River Country (past)')
counts = {}
for name, kind in RIDES:
    counts[kind] = counts.get(kind, 0) + 1
    print("%s -> %s" % (name, kind))
for kind in sorted(counts):
    print("%s: %d" % (kind, counts[kind]))
print("Total operating rides listed: %d" % len(RIDES))

